"""D0 supplied public sources, additive version 11; no financial/auth changes."""
from .d0_sources import HEADERS
TABLES=('tech_catalog_pl01','tech_catalog_pl02','tech_pl02_links','service_pl02_codes')
def migrate_source_catalogs(c,postgres=False):
    if c.execute('SELECT 1 FROM schema_migrations WHERE version=11').fetchone():return
    c.execute('ALTER TABLE catalog_imports ADD COLUMN row_count INTEGER NOT NULL DEFAULT 0')
    for table,kind in [('icd10','icd10'),('shared_lab_codes','shared_lab_codes'),('tech_catalog','tech_catalog'),('official_addresses','official_addresses')]:
        for column in HEADERS[kind]:c.execute(f"ALTER TABLE {table} ADD COLUMN {column} TEXT NOT NULL DEFAULT ''")
    identity='BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY' if postgres else 'INTEGER PRIMARY KEY AUTOINCREMENT'
    for table,kind in [('tech_catalog_pl01','tech_catalog'),('tech_catalog_pl02','tech_catalog_pl02')]:
        fields=','.join(x+" TEXT NOT NULL DEFAULT ''" for x in HEADERS[kind])
        key='code TEXT PRIMARY KEY' if kind=='tech_catalog' else f'id {identity},code TEXT NOT NULL'
        c.execute(f'''CREATE TABLE {table}({key},name TEXT NOT NULL,chapter TEXT NOT NULL DEFAULT '',{fields},search_key TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,version TEXT NOT NULL,import_id INTEGER REFERENCES catalog_imports(id))''')
        c.execute(f'CREATE INDEX idx_{table}_search ON {table}(active,search_key)')
    c.execute('CREATE UNIQUE INDEX idx_pl02_edition_row ON tech_catalog_pl02(import_id,stt)')
    c.execute('CREATE UNIQUE INDEX idx_icd_canonical ON icd10(ma_benh_khong_dau) WHERE ma_benh_khong_dau<>\'\'')
    c.execute('CREATE UNIQUE INDEX idx_pl01_original ON tech_catalog_pl01(ma_ky_thuat)')
    c.execute('''CREATE TABLE tech_pl02_links(pl02_id BIGINT NOT NULL REFERENCES tech_catalog_pl02(id),pl02_stt TEXT NOT NULL,position INTEGER NOT NULL,raw_token TEXT NOT NULL,pl01_code TEXT REFERENCES tech_catalog_pl01(ma_ky_thuat),needs_review INTEGER NOT NULL,PRIMARY KEY(pl02_id,position))''')
    c.execute('CREATE TABLE service_pl02_codes(service_id INTEGER NOT NULL REFERENCES service_catalog(id),pl02_id BIGINT NOT NULL REFERENCES tech_catalog_pl02(id),PRIMARY KEY(service_id,pl02_id))')
    c.execute('INSERT INTO schema_migrations(version) VALUES(11)')
    from .d0_sources import seed_sources
    from datetime import datetime,timezone
    seed_sources(c,datetime.now(timezone.utc).isoformat())
